query QueryProductSingleCollectionQuery($request) {
  id
  name
  status
  can_appeal
  description
  price
  original_image_url
  request_image_url
  value
  xwa_product_catalog_get_single_collection {
    collection {
      status_info {
        reject_reason
        commerce_url
        products {
          retailer_id
          is_hidden
          is_sanctioned
          product_availability
          max_available
          url
          shimmed_url
          currency
          status_info {
            sale_price {
              start_date
              end_date
              media {
                images {
                  videos {
                    original_video_url
                    thumbnail_url
                    belongs_to
                    compliance_category
                    compliance_info {
                      country_code_origin
                      importer_name
                      importer_address {
                        street1
                        street2
                        postal_code
                        city
                        region
                        country_code
                        variant_info {
                          listing_details {
                            multi_price
                            lowest_price
                            availability {
                              listing {
                                is_available
                                options {
                                  product_id
                                  types {
                                    options {
                                      thumbnail_media {
                                        original_dimensions {
                                          height
                                          width
                                          variant_properties {
                                            paging {
                                              after
                                            }
                                          }
                                        }
                                      }
                                    }
                                  }
                                }
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
